// 新会面段只保真实原Action与终态；原三源和旧personal_appointments visitor均不追加字段。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "visit_appointment_meeting_state.hpp"
#include "resident/domains/interaction/s3_leaf_life_codec.hpp"
#include "resident/domains/interaction/s3_event_time_codec.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/interaction/interaction_source_projection.hpp"
#include <set>
namespace hanmo::resident {namespace {
template<class A>Status contact(A& a,PersonalAppointmentContact& v){a.field("actor_id",v.actor_id);a.field("provider_actor_id",v.provider_actor_id);a.field("session_id",v.session_id);a.field("place_id",v.place_id);a.field("role_id",v.role_id);a.field("dialogue_id",v.dialogue_id);a.field("node_id",v.node_id);return a.field("tick",v.tick);}
template<class A>Status receipt(A& a,VisitAppointmentPlayerReceipt& v){a.field("result_id",v.result_id);a.field("request_actor_id",v.request_actor_id);a.field("request_sequence",v.request_sequence);return a.field("result_revision",v.result_revision);}
template<class A>Status started(A& a,VisitAppointmentMeetingStarted& v){a.field("fact_id",v.fact_id);a.field("invitation_fact_id",v.invitation_fact_id);a.field("acceptance_fact_id",v.acceptance_fact_id);a.field("action_id",v.action_id);a.object("contact",[&](auto& c){return contact(c,v.contact);});return a.optional("player_receipt",v.player_receipt,[](auto& c,auto& r){return receipt(c,r);});}
template<class A>Status cancelled(A& a,VisitAppointmentMeetingCancelled& v){a.field("fact_id",v.fact_id);a.field("invitation_fact_id",v.invitation_fact_id);a.field("acceptance_fact_id",v.acceptance_fact_id);a.object("contact",[&](auto& c){return contact(c,v.contact);});return a.optional("player_receipt",v.player_receipt,[](auto& c,auto& r){return receipt(c,r);});}
template<class A>Status finished(A& a,VisitAppointmentMeetingFinished& v){a.field("fact_id",v.fact_id);a.field("invitation_fact_id",v.invitation_fact_id);a.field("start_fact_id",v.start_fact_id);a.field("action_id",v.action_id);a.field("tick",v.tick);a.field("success",v.success);a.field("reason",v.reason);return a.optional("player_receipt",v.player_receipt,[](auto& c,auto& r){return receipt(c,r);});}
template<class A>Status state(A& a,VisitAppointmentMeetingState& v){a.field("version",v.version);if(v.version!=1&&v.version!=2)return a.reject("UnsupportedVisitAppointmentMeetingVersion");auto s=dynamic_codec::table(a,"started",v.started,[](auto& c,auto& r){return started(c,r);});if(!s.ok)return s;s=dynamic_codec::table(a,"cancelled",v.cancelled,[](auto& c,auto& r){return cancelled(c,r);});if(!s.ok)return s;s=dynamic_codec::table(a,"finished",v.finished,[](auto& c,auto& r){return finished(c,r);});if(!s.ok)return s;if(v.version==1)return v.life_sources.empty()&&v.temporal_events.empty()?a.status():a.reject("UnselectedVisitAppointmentMeetingTime2");s=dynamic_codec::table(a,"life_sources",v.life_sources,[](auto&c,auto&r){c.object("death_ref",[&](auto&d){return s3_leaf_life_codec::death(d,r.death_ref);});c.field("invitation_fact_id",r.invitation_fact_id);c.field("acceptance_fact_id",r.acceptance_fact_id);dynamic_codec::enumeration(c,"role",r.role,1);return c.object("effect",[&](auto&d){return s3_leaf_life_codec::fields(d,r.effect,2);});});if(!s.ok)return s;return dynamic_codec::table(a,"temporal_events",v.temporal_events,[](auto&c,auto&r){return s3_event_time_codec::fields(c,r);});}
Status unique(const BoundaryValue& v,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("VisitAppointmentMeetingTooDeep");if(const auto* d=v.as<BoundaryValue::Dict>()){if(d->size()>CodecVisitor::max_items)return common_failure("VisitAppointmentMeetingTooLarge");std::set<StableId> keys;for(const auto& row:*d){if(!keys.insert(row.first).second)return common_failure("DuplicateVisitAppointmentMeetingField",row.first);auto valid=unique(row.second,depth+1);if(!valid.ok)return valid;}}if(const auto* rows=v.as<BoundaryValue::Array>()){if(rows->size()>CodecVisitor::max_items)return common_failure("VisitAppointmentMeetingTooLarge");for(const auto& row:*rows){auto valid=unique(row,depth+1);if(!valid.ok)return valid;}}return common_success();}
}
Status visit_visit_appointment_meetings_checkpoint(CodecVisitor& c,VisitAppointmentMeetingState& s){return state(c,s);}
Status emit_visit_appointment_meetings_fields(ProjectionWriter&w,const VisitAppointmentMeetingState&v){dynamic_projection::Archive a(w);return state(a,const_cast<VisitAppointmentMeetingState&>(v));}
BoundaryValue encode_visit_appointment_meetings(const VisitAppointmentMeetingState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_visit_appointment_meetings_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Outcome<VisitAppointmentMeetingState> decode_visit_appointment_meetings(const BoundaryValue& v){auto checked=unique(v);if(!checked.ok)return {false,{},checked.error};VisitAppointmentMeetingState s;dynamic_codec::JsonArchive a(v);checked=state(a,s);if(checked.ok)checked=a.finish();return checked.ok?Outcome<VisitAppointmentMeetingState>{true,std::move(s),{}}:Outcome<VisitAppointmentMeetingState>{false,{},checked.error};}
Status emit_visit_appointment_meeting_action_fields(ProjectionWriter&w,const VisitAppointmentMeetingStarted&s){w.field("start_fact_id",s.fact_id);w.field("invitation_fact_id",s.invitation_fact_id);w.field("acceptance_fact_id",s.acceptance_fact_id);w.field("action_id",s.action_id);w.field("actor_id",s.contact.actor_id);w.field("provider_actor_id",s.contact.provider_actor_id);w.field("session_id",s.contact.session_id);w.field("started_tick",s.contact.tick);return w.status();}
BoundaryValue encode_visit_appointment_meeting_action(const VisitAppointmentMeetingStarted& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_visit_appointment_meeting_action_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Status emit_visit_appointment_meeting_fact_fields(ProjectionWriter&w,const VisitAppointmentMeetingState&s,const StableId&id,const FactRecord*expected){dynamic_projection::Archive a(w);Status valid;StableId kind;const StableId*actual_id=nullptr;if(const auto*row=s.started.find(id)){valid=started(a,const_cast<VisitAppointmentMeetingStarted&>(*row));kind=visit_appointment_meeting_started_kind;actual_id=&row->fact_id;}else if(const auto*row=s.cancelled.find(id)){valid=cancelled(a,const_cast<VisitAppointmentMeetingCancelled&>(*row));kind=visit_appointment_meeting_cancelled_kind;actual_id=&row->fact_id;}else if(const auto*row=s.finished.find(id)){valid=finished(a,const_cast<VisitAppointmentMeetingFinished&>(*row));kind=visit_appointment_meeting_finished_kind;actual_id=&row->fact_id;}else return common_failure("UnknownVisitAppointmentMeetingFact",id);if(!valid.ok)return valid;if(expected&&(!actual_id||*actual_id!=id||kind!=expected->kind))return common_failure("VisitAppointmentFactMismatch",id);w.field("kind",kind);w.text("domain",std::string_view(visit_appointment_meeting_module));return w.status();}
Outcome<BoundaryValue> encode_visit_appointment_meeting_fact(const VisitAppointmentMeetingState& s,const StableId& id){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_visit_appointment_meeting_fact_fields(out,s,id);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
}
